int main(void) {
    long long N;
    if (scanf("%lld", &N) != 1) return 0;

    int M = (int)(N / 2);

    /* dp[i][j]:
       after processing i pairs, stack has size j,
       and the top character is:
       0 = none (only when j=0)
       1 = A
       2 = B
       3 = C

       We only need previous/current layers.
    */
    long long (*prev)[4] = calloc((M + 2), sizeof(*prev));
    long long (*curr)[4] = calloc((M + 2), sizeof(*curr));
    if (!prev || !curr) return 0;

    prev[0][0] = 1;

    for (int i = 0; i < M; i++) {
        memset(curr, 0, (M + 2) * sizeof(*curr));

        for (int j = 0; j <= i; j++) {
            for (int t = 0; t < 4; t++) {
                long long ways = prev[j][t];
                if (!ways) continue;

                /* Push a new pair:
                   first char can be any of 3 letters,
                   second char must be different from first (otherwise immediate erase),
                   and also not forbidden pair AB/BA if different.
                   Valid ordered non-erasable pairs are:
                   AC, BC, CA, CB  -> 4 kinds
                   They determine the new top (second char).
                */

                if (j == 0) {
                    /* No previous top, all 4 pairs allowed */
                    curr[j + 1][3] = (curr[j + 1][3] + ways * 2) % MOD; /* AC, BC */
                    curr[j + 1][1] = (curr[j + 1][1] + ways) % MOD;     /* CA */
                    curr[j + 1][2] = (curr[j + 1][2] + ways) % MOD;     /* CB */
                } else {
                    /* Pair can be erased internally only if equal chars, which we exclude.
                       After appending xy, reduction depends only on whether x matches current top.
                       Since xy is non-erasable, x!=y and (x,y)!=(A,B),(B,A).
                       If x == top, then x erases with top, leaving y as new top at same height j.
                       Otherwise pair stays, increasing height to j+1 with top y.
                    */

                    /* Enumerate 4 valid ordered pairs */
                    int x[4] = {1, 2, 3, 3}; /* A, B, C, C */
                    int y[4] = {3, 3, 1, 2}; /* C, C, A, B */

                    for (int k = 0; k < 4; k++) {
                        if (x[k] == t) {
                            curr[j][y[k]] = (curr[j][y[k]] + ways) % MOD;
                        } else {
                            curr[j + 1][y[k]] = (curr[j + 1][y[k]] + ways) % MOD;
                        }
                    }
                }
            }
        }

        long long (*tmp)[4] = prev;
        prev = curr;
        curr = tmp;
    }

    /* To be fully reducible, final stack height must be 0 */
    printf("%lld\n", prev[0][0] % MOD);

    free(prev);
    free(curr);
    return 0;
}

