int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    // dp[top] = number of ways, top: 0=empty, 1=A, 2=B, 3=C
    vector<long long> dp(4, 0);
    dp[0] = 1; // empty string

    for (int i = 0; i < N; i++) {
        vector<long long> ndp(4, 0);
        for (int top = 0; top < 4; top++) {
            if (dp[top] == 0) continue;
            for (char c : {'A', 'B', 'C'}) {
                int ci = (c == 'A' ? 1 : (c == 'B' ? 2 : 3));
                if (top == 0) {
                    // push
                    ndp[ci] = (ndp[ci] + dp[top]) % MOD;
                } else {
                    // check if can erase
                    if ((top == 1 && ci == 2) || (top == 2 && ci == 1)) {
                        // AB or BA -> cannot erase, must push
                        ndp[ci] = (ndp[ci] + dp[top]) % MOD;
                    } else {
                        // erase -> top becomes 0
                        ndp[0] = (ndp[0] + dp[top]) % MOD;
                    }
                }
            }
        }
        dp = ndp;
    }

    cout << dp[0] % MOD << "\n";
    return 0;
}

