using namespace std;

static const long long MOD = 998244353;

// Fast exponentiation modulo MOD
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    cin >> N;

    // Let good pairs be all pairs except AB and BA.
    // A string is reducible iff it can be fully matched by noncrossing adjacent removals
    // using only good pairs.
    //
    // DP by stack language / context-free grammar leads to:
    // If f[n] = number of reducible strings of length 2n, then
    // f[0] = 1
    // f[n] = sum_{k=0}^{n-1} f[k] * f[n-1-k] * g_{n-1-k}
    // where g[m] is the number of letters x such that x ... x can wrap a reducible block
    // of length 2m. Tracking ending possibilities gives a 2-state compression, and
    // the resulting total count simplifies to:
    //
    // f[n] = 2^n * Catalan(n)
    //
    // Therefore answer for even N is:
    // ans = 2^(N/2) * Catalan(N/2) mod MOD
    //
    // Catalan(n) = C(2n,n)/(n+1)
    //
    // Since N can be large, compute with factorials up to N.

    long long n = N / 2;

    vector<long long> fact(N + 1), ifact(N + 1);
    fact[0] = 1;
    for (long long i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;

    ifact[N] = modpow(fact[N], MOD - 2);
    for (long long i = N; i >= 1; --i) ifact[i - 1] = ifact[i] * i % MOD;

    auto C = [&](long long a, long long b) -> long long {
        if (b < 0 || b > a) return 0;
        return fact[a] * ifact[b] % MOD * ifact[a - b] % MOD;
    };

    long long catalan = C(2 * n, n) * modpow(n + 1, MOD - 2) % MOD;
    long long ans = modpow(2, n) * catalan % MOD;

    cout << ans << '\n';
    return 0;
}

