public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        int m = N / 2;

        // dp[i][j]:
        // number of valid reducible strings of length 2*i
        // with exactly j letters C.
        long[][] dp = new long[m + 1][m + 1];
        dp[0][0] = 1;

        // We build a reducible string by taking the last erased pair,
        // which must be some erasable pair x y wrapping two reducible parts:
        //   S = x + L + y + R
        // where L and R are reducible.
        //
        // Allowed erasable pairs are:
        // AA, AC, BB, BC, CA, CB, CC   (7 types)
        // Among them, number of C's in the pair is:
        // 0: AA, BB  -> 2 types
        // 1: AC, BC, CA, CB -> 4 types
        // 2: CC -> 1 type
        //
        // This yields:
        // dp[i][j] = sum over split:
        //   2 * dp[a][c] * dp[b][j-c]
        // + 4 * dp[a][c] * dp[b][j-c-1]
        // + 1 * dp[a][c] * dp[b][j-c-2]
        // where a+b=i-1.
        //
        // Summing over j gives total f[i]:
        // f[i] = 7 * sum_{a+b=i-1} f[a]f[b]
        // Catalan-like, but we need the exact C-count because the statement
        // asks for all strings over {A,B,C}; final answer is sum_j dp[m][j].
        //
        // We can compute directly in O(m^3), enough for moderate constraints.
        // Then answer is sum_j dp[m][j].

        for (int pairs = 1; pairs <= m; pairs++) {
            for (int left = 0; left <= pairs - 1; left++) {
                int right = pairs - 1 - left;
                for (int cLeft = 0; cLeft <= left; cLeft++) {
                    long vLeft = dp[left][cLeft];
                    if (vLeft == 0) continue;
                    for (int cRight = 0; cRight <= right; cRight++) {
                        long ways = vLeft * dp[right][cRight] % MOD;
                        if (ways == 0) continue;

                        int baseC = cLeft + cRight;

                        // pair contributes 0 C: AA, BB
                        dp[pairs][baseC] = (dp[pairs][baseC] + 2 * ways) % MOD;

                        // pair contributes 1 C: AC, BC, CA, CB
                        if (baseC + 1 <= pairs) {
                            dp[pairs][baseC + 1] = (dp[pairs][baseC + 1] + 4 * ways) % MOD;
                        }

                        // pair contributes 2 C: CC
                        if (baseC + 2 <= pairs) {
                            dp[pairs][baseC + 2] = (dp[pairs][baseC + 2] + ways) % MOD;
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int j = 0; j <= m; j++) {
            ans += dp[m][j];
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

