def solve():
    N = int(input())

    # Stack state: tuple of characters, where adjacent are always AB or BA pattern
    # Represent as (length, bottom_char) - alternating sequence
    # State: (pos, stack_len, bottom_char) where bottom_char in {0=A, 1=B, -1=empty}

    from collections import defaultdict

    # dp[stack] = count
    # stack represented as tuple
    dp = defaultdict(int)
    dp[()] = 1

    chars = ['A', 'B', 'C']

    def can_erase(a, b):
        return not (a == 'A' and b == 'B') and not (a == 'B' and b == 'A')

    for _ in range(N):
        ndp = defaultdict(int)
        for stack, cnt in dp.items():
            for c in chars:
                if stack and can_erase(stack[-1], c):
                    ndp[stack[:-1]] = (ndp[stack[:-1]] + cnt) % MOD
                else:
                    ndp[stack + (c,)] = (ndp[stack + (c,)] + cnt) % MOD
        dp = ndp

